Post Date: 2011-06-10T03:08:14Z
Current Date: April 4 2025
Title: How to access mesh object after loader callback?
Description: Hi.  I have imported a model from Blender successfully using loader.load() through a callback function.  My problem is that I can't seem to find a way to influence the object's properties after it's gone through the callback.  Here is the simplified code:

```
               var container, stats;
        var camera, scene, renderer;
        var mesh, mesh2, mesh3, light;      
        var windowHalfX = window.innerWidth / 2;
        var windowHalfY = window.innerHeight / 2;
        var cross;
        var VIEW_ANGLE = 20;
        var ASPECT = window.innerWidth / window.innerHeight;
        var NEAR = 0.1;
        var FAR = 30000;

        init();
        animate();

        var WIDTH = 400, HEIGHT = 300;

        function init() {
            container = document.getElementById( 'container' );         
            renderer = new THREE.WebGLRenderer();               
            camera = new THREE.Camera( VIEW_ANGLE, ASPECT, NEAR, FAR );
            scene = new THREE.Scene();                  
            camera.position.z = 0;
            camera.target.position.z = 0;           
            camera.position.y = 2800;
            camera.target.position.y = 0;           
            camera.position.x = 17800;
            camera.target.position.x = 0;           
            camera.updateMatrix();

            ambientLight = new THREE.AmbientLight( 0x444444 );
            scene.addLight( ambientLight );
            pointLight = new THREE.PointLight( 0xffffff );
            pointLight.position.z = 600;
            scene.addLight( pointLight );

            var loader = new THREE.JSONLoader();
            loader.load( { model: "models/charlie2.js", callback: createScene } );              
            renderer.setSize( window.innerWidth, window.innerHeight );
            container.appendChild( renderer.domElement );

        }


        function createScene( geometry) {
            var material = new THREE.MeshFaceMaterial();
            mesh = THREE.SceneUtils.addMesh( scene, geometry, 250, 0, 0, 0, 0, 0, 0,material) ; 
        }

        function animate() {
            requestAnimationFrame( animate );
            renderer.render( scene, camera );           
            stats.update();
        }
```

What I want to do is simple: turn the "mesh" variable created in createScene() into a sort of "global variable", so that I can affect the object's position, rotation and scale properties dynamically from other parts of the code.  

Is there perhaps a way that the callback from loader.load() can return the mesh so that I can use it's position as needed from other functions in the application? 

Thanks very much in advance for your help.  

Mark


